# This module is part of python-sqlparse and is released under
# the BSD License: https://opensource.org/licenses/BSD-3-Clause
#
# Example script to extract table names and related information
# from statements.

import sqlparse
from sqlparse.sql import IdentifierList, Identifier
from sqlparse.tokens import Keyword, DML


def is_subselect(parsed):
    if not parsed.is_group:
        return False
    for item in parsed.tokens:
        if item.ttype is DML and item.value.upper() == 'SELECT':
            return True
    return False


# Keywords that introduce a table reference.
TBL_START = (
    'FROM', 'JOIN', 'INNER JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'FULL JOIN',
    'LEFT OUTER JOIN', 'RIGHT OUTER JOIN', 'FULL OUTER JOIN', 'CROSS JOIN',
    'NATURAL JOIN', 'STRAIGHT_JOIN', 'UPDATE', 'INTO', 'TABLE',
)

# Keywords that end a table reference.
TBL_STOP = (
    'WHERE', 'GROUP BY', 'ORDER BY', 'HAVING', 'LIMIT', 'OFFSET', 'FETCH',
    'UNION', 'UNION ALL', 'EXCEPT', 'INTERSECT', 'ON', 'USING', 'SET',
    'VALUES', 'RETURNING', 'WINDOW',
)


def extract_from_part(parsed):
    tbl_prefix_seen = False
    for item in parsed.tokens:
        if item.is_group:
            yield from extract_from_part(item)
        if tbl_prefix_seen:
            if is_subselect(item):
                yield from extract_from_part(item)
            elif item.ttype is Keyword:
                if item.normalized in TBL_START:
                    # e.g. another JOIN follows
                    continue
                if item.normalized in TBL_STOP:
                    tbl_prefix_seen = False
            else:
                yield item
        elif item.ttype is Keyword and item.normalized in TBL_START:
            tbl_prefix_seen = True


def extract_table_identifiers(token_stream):
    for item in token_stream:
        if isinstance(item, IdentifierList):
            for identifier in item.get_identifiers():
                name = identifier.get_real_name()
                if name is not None:
                    yield name
        elif isinstance(item, Identifier):
            name = item.get_real_name()
            if name is not None:
                yield name
        elif item.ttype is Keyword:
            yield item.value


def extract_tables(sql):
    """Extract table names from a statement.

    Returns a list of table names found in the FROM / JOIN parts of
    the statement.
    """
    parsed = sqlparse.parse(sql)
    if not parsed:
        return []
    stream = extract_from_part(parsed[0])
    return list(extract_table_identifiers(stream))


if __name__ == '__main__':
    sql = """
    select K.a, K.b from (select H.b from (select G.c from (select F.d from
    (select E.e from A, B, C, D, E), F), G), H), I, J, K order by 1,2;
    """

    print('Tables: {!r}'.format(extract_tables(sql)))

